---------------------------------------------------------------------------
-- Election
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[Election] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    Name NVARCHAR(255) NOT NULL,
    Description NVARCHAR(MAX) NULL,
    ElectionTypeID UNIQUEIDENTIFIER NOT NULL,
    Status NVARCHAR(20) NOT NULL DEFAULT N'Draft',
    SecrecyMode NVARCHAR(20) NOT NULL DEFAULT N'Secret',
    AssuranceTier NVARCHAR(20) NOT NULL DEFAULT N'Standard',
    EligibilitySourceTypeID UNIQUEIDENTIFIER NULL,
    EligibilitySourceSettings NVARCHAR(MAX) NULL,
    RecordDate DATETIMEOFFSET NULL,
    TimeZone NVARCHAR(64) NOT NULL DEFAULT N'UTC',
    NominationsOpenAt DATETIMEOFFSET NULL,
    NominationsCloseAt DATETIMEOFFSET NULL,
    OpensAt DATETIMEOFFSET NULL,
    ClosesAt DATETIMEOFFSET NULL,
    ProxyDeadline DATETIMEOFFSET NULL,
    ChallengeWindowEndsAt DATETIMEOFFSET NULL,
    AllowRevote BIT NOT NULL DEFAULT 0,
    ResultsTiming NVARCHAR(20) NOT NULL DEFAULT N'AfterClose',
    ResultsAudience NVARCHAR(20) NOT NULL DEFAULT N'Voters',
    ResultsMinCast INT NOT NULL DEFAULT 5,
    WeightClassMinSize INT NOT NULL DEFAULT 5,
    LiveRefreshEveryBallots INT NULL,
    LiveRefreshMinMinutes INT NULL,
    PublishPollBook BIT NOT NULL DEFAULT 0,
    RollFrozenAt DATETIMEOFFSET NULL,
    RollHash NVARCHAR(128) NULL,
    TrusteeThreshold INT NULL,
    ElectionPublicKey NVARCHAR(MAX) NULL,
    Configuration NVARCHAR(MAX) NULL,
    CONSTRAINT PK_Election PRIMARY KEY (ID),
    CONSTRAINT FK_Election_ElectionType FOREIGN KEY (ElectionTypeID) REFERENCES [${flyway:defaultSchema}].[ElectionType](ID),
    CONSTRAINT FK_Election_EligibilitySourceType FOREIGN KEY (EligibilitySourceTypeID) REFERENCES [${flyway:defaultSchema}].[EligibilitySourceType](ID),
    CONSTRAINT CK_Election_Status CHECK (Status IN (N'Draft', N'Nominations', N'Ready', N'Open', N'Closed', N'Tallied', N'Certified', N'Cancelled')),
    CONSTRAINT CK_Election_SecrecyMode CHECK (SecrecyMode IN (N'Open', N'Confidential', N'Secret')),
    CONSTRAINT CK_Election_AssuranceTier CHECK (AssuranceTier IN (N'Standard', N'HighAssurance', N'Verifiable')),
    CONSTRAINT CK_Election_ResultsTiming CHECK (ResultsTiming IN (N'AfterClose', N'AfterVoting', N'Live', N'AdministratorsOnly')),
    CONSTRAINT CK_Election_ResultsAudience CHECK (ResultsAudience IN (N'Voters', N'Eligible', N'HostMembers', N'Public', N'Administrators')),
    CONSTRAINT CK_Election_ResultsMinCast CHECK (ResultsMinCast >= 0),
    CONSTRAINT CK_Election_WeightClassMinSize CHECK (WeightClassMinSize >= 1),
    CONSTRAINT CK_Election_LiveRefresh CHECK ((LiveRefreshEveryBallots IS NULL OR LiveRefreshEveryBallots >= 1) AND (LiveRefreshMinMinutes IS NULL OR LiveRefreshMinMinutes >= 1)),
    CONSTRAINT CK_Election_Window CHECK (OpensAt IS NULL OR ClosesAt IS NULL OR ClosesAt > OpensAt),
    CONSTRAINT CK_Election_NominationWindow CHECK (NominationsOpenAt IS NULL OR NominationsCloseAt IS NULL OR NominationsCloseAt > NominationsOpenAt),
    CONSTRAINT CK_Election_SecretIsFinal CHECK (SecrecyMode <> N'Secret' OR AllowRevote = 0),
    CONSTRAINT CK_Election_RunningResultsTierA CHECK (AssuranceTier = N'Standard' OR ResultsTiming = N'AfterClose'),
    CONSTRAINT CK_Election_TrusteeThreshold CHECK (TrusteeThreshold IS NULL OR TrusteeThreshold >= 1)
);
GO

---------------------------------------------------------------------------
-- ElectionAnchor
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[ElectionAnchor] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ElectionID UNIQUEIDENTIFIER NOT NULL,
    EntityID UNIQUEIDENTIFIER NOT NULL,
    RecordID NVARCHAR(450) NOT NULL,
    Role NVARCHAR(50) NOT NULL DEFAULT N'Subject',
    IsPrimary BIT NOT NULL DEFAULT 0,
    Sequence INT NOT NULL DEFAULT 0,
    CONSTRAINT PK_ElectionAnchor PRIMARY KEY (ID),
    CONSTRAINT FK_ElectionAnchor_Election FOREIGN KEY (ElectionID) REFERENCES [${flyway:defaultSchema}].[Election](ID),
    CONSTRAINT FK_ElectionAnchor_Entity FOREIGN KEY (EntityID) REFERENCES [${mjSchema}].[Entity](ID),
    CONSTRAINT UQ_ElectionAnchor_Record UNIQUE (ElectionID, EntityID, RecordID, Role)
);
GO

---------------------------------------------------------------------------
-- Contest
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[Contest] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ElectionID UNIQUEIDENTIFIER NOT NULL,
    Name NVARCHAR(500) NOT NULL,
    Description NVARCHAR(MAX) NULL,
    Sequence INT NOT NULL DEFAULT 0,
    Kind NVARCHAR(20) NOT NULL,
    Seats INT NOT NULL DEFAULT 1,
    TallyMethodID UNIQUEIDENTIFIER NOT NULL,
    Threshold NVARCHAR(20) NOT NULL DEFAULT N'None',
    CustomThreshold DECIMAL(7,6) NULL,
    ThresholdBasis NVARCHAR(20) NOT NULL DEFAULT N'VotesCast',
    AllowAbstain BIT NOT NULL DEFAULT 1,
    AllowWriteIn BIT NOT NULL DEFAULT 0,
    MinSelections INT NOT NULL DEFAULT 0,
    MaxSelections INT NULL,
    VotingClassFilter NVARCHAR(100) NULL,
    TieBreakMethod NVARCHAR(20) NOT NULL DEFAULT N'Lot',
    CONSTRAINT PK_Contest PRIMARY KEY (ID),
    CONSTRAINT FK_Contest_Election FOREIGN KEY (ElectionID) REFERENCES [${flyway:defaultSchema}].[Election](ID),
    CONSTRAINT FK_Contest_TallyMethod FOREIGN KEY (TallyMethodID) REFERENCES [${flyway:defaultSchema}].[TallyMethod](ID),
    CONSTRAINT CK_Contest_Kind CHECK (Kind IN (N'Motion', N'Office', N'Question', N'Amendment', N'StandardsItem')),
    CONSTRAINT CK_Contest_Threshold CHECK (Threshold IN (N'None', N'Majority', N'ThreeFifths', N'TwoThirds', N'ThreeQuarters', N'Unanimous', N'Custom')),
    CONSTRAINT CK_Contest_ThresholdBasis CHECK (ThresholdBasis IN (N'VotesCast', N'Eligible')),
    CONSTRAINT CK_Contest_TieBreakMethod CHECK (TieBreakMethod IN (N'Lot', N'Administrator')),
    CONSTRAINT CK_Contest_Seats CHECK (Seats >= 1),
    CONSTRAINT CK_Contest_CustomThreshold CHECK ((Threshold = N'Custom' AND CustomThreshold > 0 AND CustomThreshold <= 1) OR (Threshold <> N'Custom' AND CustomThreshold IS NULL)),
    CONSTRAINT CK_Contest_Selections CHECK (MinSelections >= 0 AND (MaxSelections IS NULL OR MaxSelections >= MinSelections))
);
GO

---------------------------------------------------------------------------
-- ContestOption
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[ContestOption] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ContestID UNIQUEIDENTIFIER NOT NULL,
    Label NVARCHAR(500) NOT NULL,
    Description NVARCHAR(MAX) NULL,
    CandidatePersonID UNIQUEIDENTIFIER NULL,
    StatementFileID UNIQUEIDENTIFIER NULL,
    PhotoFileID UNIQUEIDENTIFIER NULL,
    Sequence INT NOT NULL DEFAULT 0,
    IsWriteIn BIT NOT NULL DEFAULT 0,
    Status NVARCHAR(20) NOT NULL DEFAULT N'Active',
    CONSTRAINT PK_ContestOption PRIMARY KEY (ID),
    CONSTRAINT FK_ContestOption_Contest FOREIGN KEY (ContestID) REFERENCES [${flyway:defaultSchema}].[Contest](ID),
    CONSTRAINT FK_ContestOption_CandidatePerson FOREIGN KEY (CandidatePersonID) REFERENCES [__mj_BizAppsCommon].[Person](ID),
    CONSTRAINT FK_ContestOption_StatementFile FOREIGN KEY (StatementFileID) REFERENCES [${mjSchema}].[File](ID),
    CONSTRAINT FK_ContestOption_PhotoFile FOREIGN KEY (PhotoFileID) REFERENCES [${mjSchema}].[File](ID),
    CONSTRAINT CK_ContestOption_Status CHECK (Status IN (N'Active', N'Withdrawn'))
);
GO

---------------------------------------------------------------------------
-- Nomination
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[Nomination] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ContestID UNIQUEIDENTIFIER NOT NULL,
    NomineePersonID UNIQUEIDENTIFIER NOT NULL,
    NominatedByPersonID UNIQUEIDENTIFIER NULL,
    Status NVARCHAR(20) NOT NULL DEFAULT N'Submitted',
    Statement NVARCHAR(MAX) NULL,
    SubmittedAt DATETIMEOFFSET NOT NULL DEFAULT SYSDATETIMEOFFSET(),
    DecidedAt DATETIMEOFFSET NULL,
    DecisionNotes NVARCHAR(MAX) NULL,
    ContestOptionID UNIQUEIDENTIFIER NULL,
    CONSTRAINT PK_Nomination PRIMARY KEY (ID),
    CONSTRAINT FK_Nomination_Contest FOREIGN KEY (ContestID) REFERENCES [${flyway:defaultSchema}].[Contest](ID),
    CONSTRAINT FK_Nomination_NomineePerson FOREIGN KEY (NomineePersonID) REFERENCES [__mj_BizAppsCommon].[Person](ID),
    CONSTRAINT FK_Nomination_NominatedByPerson FOREIGN KEY (NominatedByPersonID) REFERENCES [__mj_BizAppsCommon].[Person](ID),
    CONSTRAINT FK_Nomination_ContestOption FOREIGN KEY (ContestOptionID) REFERENCES [${flyway:defaultSchema}].[ContestOption](ID),
    CONSTRAINT UQ_Nomination_ContestNominee UNIQUE (ContestID, NomineePersonID),
    CONSTRAINT CK_Nomination_Status CHECK (Status IN (N'Submitted', N'Accepted', N'Declined', N'Approved', N'Rejected', N'Withdrawn'))
);
GO

---------------------------------------------------------------------------
-- NominationEndorsement
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[NominationEndorsement] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
