    CONSTRAINT FK_NominationEndorsement_Nomination FOREIGN KEY (NominationID) REFERENCES [${flyway:defaultSchema}].[Nomination](ID),
    CONSTRAINT FK_NominationEndorsement_EndorserPerson FOREIGN KEY (EndorserPersonID) REFERENCES [__mj_BizAppsCommon].[Person](ID),
    CONSTRAINT UQ_NominationEndorsement UNIQUE (NominationID, EndorserPersonID),
