);
GO

---------------------------------------------------------------------------
-- EligibleVoter
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[EligibleVoter] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ElectionID UNIQUEIDENTIFIER NOT NULL,
    PersonID UNIQUEIDENTIFIER NOT NULL,
    RepresentingOrganizationID UNIQUEIDENTIFIER NULL,
    VotingClass NVARCHAR(100) NULL,
    Weight DECIMAL(18,6) NOT NULL DEFAULT 1,
    SourceKey NVARCHAR(255) NULL,
    Status NVARCHAR(20) NOT NULL DEFAULT N'Eligible',
    StatusReason NVARCHAR(MAX) NULL,
    AddedAfterFreeze BIT NOT NULL DEFAULT 0,
    CONSTRAINT PK_EligibleVoter PRIMARY KEY (ID),
    CONSTRAINT FK_EligibleVoter_Election FOREIGN KEY (ElectionID) REFERENCES [${flyway:defaultSchema}].[Election](ID),
    CONSTRAINT FK_EligibleVoter_Person FOREIGN KEY (PersonID) REFERENCES [__mj_BizAppsCommon].[Person](ID),
    CONSTRAINT FK_EligibleVoter_RepresentingOrganization FOREIGN KEY (RepresentingOrganizationID) REFERENCES [__mj_BizAppsCommon].[Organization](ID),
    CONSTRAINT UQ_EligibleVoter UNIQUE (ElectionID, PersonID, RepresentingOrganizationID),
    CONSTRAINT CK_EligibleVoter_Status CHECK (Status IN (N'Eligible', N'Challenged', N'Removed')),
    CONSTRAINT CK_EligibleVoter_Weight CHECK (Weight > 0)
);
GO

