    CONSTRAINT FK_VoterCredential_Method FOREIGN KEY (VoterCredentialMethodID) REFERENCES [${flyway:defaultSchema}].[VoterCredentialMethod](ID),
    CONSTRAINT FK_VoterCredential_MagicLinkInvite FOREIGN KEY (MagicLinkInviteID) REFERENCES [${mjSchema}].[MagicLinkInvite](ID),
    CONSTRAINT CK_VoterCredential_FailedAttempts CHECK (FailedAttempts >= 0)
);
GO

