---------------------------------------------------------------------------
-- ElectionTrustee
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[ElectionTrustee] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
