    DocumentVersion NVARCHAR(50) NULL,
    DocumentFileID UNIQUEIDENTIFIER NULL,
    RecirculationRound INT NOT NULL DEFAULT 0,
    PriorElectionID UNIQUEIDENTIFIER NULL,
    CONSTRAINT PK_StandardsBallotElection PRIMARY KEY (ID),
    CONSTRAINT FK_StandardsBallotElection_Election FOREIGN KEY (ID) REFERENCES [${flyway:defaultSchema}].[Election](ID),
    CONSTRAINT FK_StandardsBallotElection_DocumentFile FOREIGN KEY (DocumentFileID) REFERENCES [${mjSchema}].[File](ID),
    CONSTRAINT FK_StandardsBallotElection_PriorElection FOREIGN KEY (PriorElectionID) REFERENCES [${flyway:defaultSchema}].[Election](ID),
