---------------------------------------------------------------------------
-- BallotComment
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[BallotComment] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    ContestID UNIQUEIDENTIFIER NOT NULL,
    ParticipationID UNIQUEIDENTIFIER NOT NULL,
    Sequence INT NOT NULL DEFAULT 0,
    CommentType NVARCHAR(20) NOT NULL DEFAULT N'Technical',
    DocumentReference NVARCHAR(255) NULL,
    Comment NVARCHAR(MAX) NOT NULL,
    ProposedChange NVARCHAR(MAX) NULL,
    CONSTRAINT PK_BallotComment PRIMARY KEY (ID),
    CONSTRAINT FK_BallotComment_Contest FOREIGN KEY (ContestID) REFERENCES [${flyway:defaultSchema}].[Contest](ID),
    CONSTRAINT FK_BallotComment_Participation FOREIGN KEY (ParticipationID) REFERENCES [${flyway:defaultSchema}].[Participation](ID),
    CONSTRAINT CK_BallotComment_CommentType CHECK (CommentType IN (N'General', N'Technical', N'Editorial'))
);
GO

---------------------------------------------------------------------------
-- CommentResolution
---------------------------------------------------------------------------
CREATE TABLE [${flyway:defaultSchema}].[CommentResolution] (
    ID UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),
    BallotCommentID UNIQUEIDENTIFIER NOT NULL,
    Disposition NVARCHAR(30) NOT NULL,
    Response NVARCHAR(MAX) NULL,
    ResolvedByUserID UNIQUEIDENTIFIER NULL,
    ResolvedAt DATETIMEOFFSET NOT NULL DEFAULT SYSDATETIMEOFFSET(),
    CommenterResponse NVARCHAR(20) NULL,
    CONSTRAINT PK_CommentResolution PRIMARY KEY (ID),
    CONSTRAINT FK_CommentResolution_BallotComment FOREIGN KEY (BallotCommentID) REFERENCES [${flyway:defaultSchema}].[BallotComment](ID),
    CONSTRAINT FK_CommentResolution_ResolvedByUser FOREIGN KEY (ResolvedByUserID) REFERENCES [${mjSchema}].[User](ID),
    CONSTRAINT UQ_CommentResolution_Comment UNIQUE (BallotCommentID),
    CONSTRAINT CK_CommentResolution_Disposition CHECK (Disposition IN (N'Accepted', N'AcceptedInPrinciple', N'Rejected', N'Withdrawn', N'Deferred')),
    CONSTRAINT CK_CommentResolution_CommenterResponse CHECK (CommenterResponse IN (N'Satisfied', N'Unsatisfied'))
);
GO

---------------------------------------------------------------------------
-- Invariants that are not foreign-key indexes
---------------------------------------------------------------------------
-- At most one primary anchor per election.
CREATE UNIQUE INDEX UQ_ElectionAnchor_OnePrimary
    ON [${flyway:defaultSchema}].[ElectionAnchor] (ElectionID)
    WHERE IsPrimary = 1;
GO

-- At most one active (unrevoked) credential per voter and sign-in method.
CREATE UNIQUE INDEX UQ_VoterCredential_OneActive
    ON [${flyway:defaultSchema}].[VoterCredential] (EligibleVoterID, VoterCredentialMethodID)
    WHERE RevokedAt IS NULL;
GO

